const rows = $input.all();

const output = [];
const seenIds = new Set();


/* =========================================================
   CONFIG
========================================================= */

/*
  المستويات الموجودة حاليًا في الداتا.
  إذا وسّعتِ النظام لاحقًا عدّلي الأرقام فقط.
*/
const MIN_LEARNING_LEVEL = 1;
const MAX_LEARNING_LEVEL = 6;

const MIN_MICRO_LEVEL = 1;
const MAX_MICRO_LEVEL = 110;


/*
  المواضيع المعتمدة حاليًا.

  الهدف من القائمة منع أخطاء مثل:
  Health and Emergencies.
  بدل:
  Health and Emergencies
*/
const ALLOWED_TOPICS = new Set([
  "Basics and Daily Language",
  "Daily Life and Home",
  "Family and Relationships",
  "Feelings, Opinions and Social Life",
  "Food and Restaurants",
  "General Conversation",
  "Greetings and Introductions",
  "Health and Emergencies",
  "Hobbies, Culture and Society",
  "Numbers, Time and Dates",
  "Personal Information",
  "Shopping and Money",
  "Slang and Common Expressions",
  "Technology and Communication",
  "Transportation and Directions",
  "Travel and Accommodation",
  "Work and Education",
]);


/* =========================================================
   HELPERS
========================================================= */

function toText(value, fallback = "") {
  if (
    value === null ||
    value === undefined
  ) {
    return fallback;
  }

  const result = String(value).trim();

  return result || fallback;
}


/*
  حقل نصي مطلوب.
*/
function requiredText(
  value,
  fieldName,
  rowNumber,
  id = "unknown"
) {
  const text = toText(value);

  if (!text) {
    throw new Error(
      `الصف ${rowNumber} - ID ${id}: الحقل "${fieldName}" فارغ.`
    );
  }

  return text;
}


/*
  رقم صحيح مطلوب.

  ما منستخدم fallback إلى 1،
  لأنه ممكن يخفي أخطاء في الداتا.
*/
function requiredInteger(
  value,
  fieldName,
  rowNumber,
  id
) {
  const text = toText(value);

  if (!text) {
    throw new Error(
      `الصف ${rowNumber} - ID ${id}: الحقل "${fieldName}" فارغ.`
    );
  }

  const number = Number(text);

  if (
    !Number.isFinite(number) ||
    !Number.isInteger(number)
  ) {
    throw new Error(
      `الصف ${rowNumber} - ID ${id}: "${fieldName}" يجب أن يكون رقمًا صحيحًا. القيمة الحالية: "${text}"`
    );
  }

  return number;
}


/*
  رقم اختياري.
  Difficulty غير موجود في بعض الملفات،
  لذلك إذا كان فارغًا يصبح 0.
*/
function optionalNumber(
  value,
  fieldName,
  rowNumber,
  id,
  fallback = 0
) {
  const text = toText(value);

  if (!text) {
    return fallback;
  }

  const number = Number(text);

  if (!Number.isFinite(number)) {
    throw new Error(
      `الصف ${rowNumber} - ID ${id}: "${fieldName}" ليس رقمًا صالحًا. القيمة الحالية: "${text}"`
    );
  }

  return number;
}


/* =========================================================
   PREPARE DOCUMENTS
========================================================= */

for (
  let index = 0;
  index < rows.length;
  index++
) {
  const item = rows[index];

  const row = item.json ?? {};

  /*
    +2 لأن:
    صف 1 = Header في CSV
    index يبدأ من صفر
  */
  const rowNumber = index + 2;


  /* =======================================================
     ID
  ======================================================= */

  const id = requiredText(
    row["ID"] ??
    row["Item_ID"] ??
    row["Item ID"] ??
    row["original_id"],
    "ID",
    rowNumber
  );


  /*
    مهم جدًا:
    الـID لازم يكون أرقام فقط.

    هذا يمنع المشكلة التي حصلت عندما دخل
    RAG_Text كامل داخل خانة ID.
  */
  if (!/^\d+$/.test(id)) {
    throw new Error(
      `الصف ${rowNumber}: ID غير صالح: "${id}". يجب أن يحتوي ID على أرقام فقط.`
    );
  }


  /*
    منع Duplicate IDs.
  */
  if (seenIds.has(id)) {
    throw new Error(
      `الصف ${rowNumber}: يوجد ID مكرر: ${id}`
    );
  }

  seenIds.add(id);


  /* =======================================================
     LANGUAGE CONTENT
  ======================================================= */

  const msa = requiredText(
    row["Modern Standard Arabic"] ??
    row["MSA"] ??
    row["msa"],
    "Modern Standard Arabic",
    rowNumber,
    id
  );


  const levantine = requiredText(
    row["Levantine Arabic"] ??
    row["Levantine_Arabic"] ??
    row["levantine"],
    "Levantine Arabic",
    rowNumber,
    id
  );


  const english = requiredText(
    row["English"] ??
    row["english"],
    "English",
    rowNumber,
    id
  );


  /* =======================================================
     TOPIC
  ======================================================= */

  const topic = requiredText(
    row["Topic"] ??
    row["topic"],
    "Topic",
    rowNumber,
    id
  );


  /*
    يمنع Topic مكتوب غلط أو فيه نقطة زائدة.
  */
  if (!ALLOWED_TOPICS.has(topic)) {
    throw new Error(
      `الصف ${rowNumber} - ID ${id}: Topic غير معتمد: "${topic}"`
    );
  }


  /* =======================================================
     LEARNING LEVEL
  ======================================================= */

  const learningLevel = requiredInteger(
    row["Learning_Level"] ??
    row["Learning Level"] ??
    row["Stage"] ??
    row["stage"],
    "Learning_Level",
    rowNumber,
    id
  );


  if (
    learningLevel < MIN_LEARNING_LEVEL ||
    learningLevel > MAX_LEARNING_LEVEL
  ) {
    throw new Error(
      `الصف ${rowNumber} - ID ${id}: Learning_Level خارج النطاق. القيمة: ${learningLevel}. المطلوب ${MIN_LEARNING_LEVEL}-${MAX_LEARNING_LEVEL}.`
    );
  }


  /* =======================================================
     MICRO LEVEL
  ======================================================= */

  const microLevel = requiredInteger(
    row["Micro_Level"] ??
    row["Micro Level"] ??
    row["micro_level"] ??
    row["microLevel"],
    "Micro_Level",
    rowNumber,
    id
  );


  if (
    microLevel < MIN_MICRO_LEVEL ||
    microLevel > MAX_MICRO_LEVEL
  ) {
    throw new Error(
      `الصف ${rowNumber} - ID ${id}: Micro_Level خارج النطاق. القيمة: ${microLevel}. المطلوب ${MIN_MICRO_LEVEL}-${MAX_MICRO_LEVEL}.`
    );
  }


  /* =======================================================
     OPTIONAL FIELDS
  ======================================================= */

  const difficulty = optionalNumber(
    row["Difficulty"] ??
    row["Difficulty_Score"] ??
    row["Difficulty Score"] ??
    row["difficulty"],
    "Difficulty",
    rowNumber,
    id,
    0
  );


  const itemType = toText(
    row["Item_Type"] ??
    row["Item Type"] ??
    row["item_type"]
  );


  const qualityStatus = toText(
    row["Quality_Status"] ??
    row["Quality Status"] ??
    row["quality_status"]
  );


  /* =======================================================
     EMBEDDING TEXT

     IMPORTANT:
     RAG_Text IS NOT USED.
  ======================================================= */

  const text = [
    `الفصحى: ${msa}`,
    `الشامية: ${levantine}`,
    `الإنجليزية: ${english}`,
    `الموضوع: ${topic}`,
    `المستوى: ${learningLevel}`,
    `المستوى الفرعي: ${microLevel}`,
  ].join("\n");


  /* =======================================================
     CHROMA DOCUMENT
  ======================================================= */

  output.push({
    json: {

      /*
        Document ID داخل Chroma.
      */
      id: `row-${id}`,


      /*
        هذا النص هو الذي سيتم عمل Embedding له.
      */
      text,


      /*
        Metadata التي سيستخدمها التطبيق
        في الاسترجاع والفلاتر والإجابات.
      */
      metadata: {

        /* IDs */
        item_id: id,
        original_id: id,
        source_id: id,

        /* Classification */
        topic,

        /* Main level */
        learning_level: learningLevel,

        /*
          stage محفوظ لأن Workflow الحالي
          يستخدمه في Chroma filters.
        */
        stage: learningLevel,

        /* Micro level */
        micro_level: microLevel,

        /* Difficulty */
        difficulty,

        /* Language content */
        msa,
        levantine,
        english,

        /*
          مش ضروريين للـflow الحالي،
          لكن مفيدين نحفظهم في metadata.
        */
        item_type: itemType,
        quality_status: qualityStatus,
      },
    },
  });
}


/* =========================================================
   FINAL VALIDATION
========================================================= */

if (output.length !== rows.length) {
  throw new Error(
    `عدد Documents الناتجة (${output.length}) لا يساوي عدد صفوف الداتا (${rows.length}).`
  );
}


/* =========================================================
   RETURN
========================================================= */

return output;

const sourceItems = $('Loop Over Items1').all();

return sourceItems.map((item) => {
  const data = item.json;

  const question = String(
    data.Question ??
    data.Prompt ??
    ""
  ).trim();

  // الأفضل للـRAG هو MSA_Input نفسه
  let query = String(
    data.MSA_Input ??
    ""
  ).trim();

  // احتياط: إذا MSA_Input فاضي نستخرج النص من « »
  if (!query) {
    const match =
      question.match(/«([^»]+)»/) ||
      question.match(/["“”]([^"“”]+)["“”]/);

    query = match?.[1]?.trim() || question;
  }

  return {
    json: {
      ...data,

      Question: question,
      Prompt: question,

      // النص الذي سيذهب للـRAG retrieval
      query: query,

      Test_ID: data.Test_ID ?? "",

      MSA_Input: data.MSA_Input ?? "",

      Reference_Levantine:
        data.Reference_Levantine ?? "",

      Evaluation_Type:
        data.Evaluation_Type ??
        data.Prompt_Strategy ??
        ""
    }
  };
});
